class Prepaid {
	public Boolean enrollToPrepaid() {
		return true;
	}
}

class Customer {
	public void register() {
		Prepaid prepaid = new Prepaid();
		if (prepaid.enrollToPrepaid()) {
			System.out.println("Customer enrolled to a plan");
		} else {
			throw new Exception("Exception.UNPAID_BILL");
		}
	}
}

interface Plan {
	public Boolean enrollToPlan();
}

class Prepaid implements Plan {
	public Boolean enrollToPlan() {
		return true;
	}
}

class Postpaid implements Plan {
	public Boolean enrollToPlan() {
		return true;
	}
}

class Customer {
	public void register() {
		Plan plan = new Prepaid();  // Can switch to new Postpaid()
		if (plan.enrollToPlan()) {
			System.out.println("Customer enrolled to a plan");
		} else {
			throw new Exception("Exception.UNREGISTERED_CUSTOMER");
		}
	}
}

class Customer {
	Plan plan;

	public Customer(Plan plan) {
		this.plan = plan;
	}

	public void register() {
		if (plan.enrollToPlan()) {
			System.out.println("Customer enrolled to a plan");
		} else {
			throw new Exception("Exception.UNREGISTERED_CUSTOMER");
		}
	}
}

class Tester {
	public static void main(String[] args) {
		Plan plan = new Prepaid();        // Can be changed to Postpaid without touching Customer
		Customer customer = new Customer(plan);
		customer.register();
	}
}

@Component
class Customer {
	private Plan plan;

	@Autowired
	public Customer(Plan plan) {
		this.plan = plan;
	}
}

@Component
class Customer {
	private Plan plan;

	@Autowired
	public void setPlan(Plan plan) {
		this.plan = plan;
	}
}

